import{_ as e,c as t,o,ag as r}from"./chunks/framework.Cycwnjj0.js";const a="/assets/add-classic-editor-block-in-a-post.CmrYxuV_.webp",i="/assets/add-media-option-from-the-classic-editor.dP_S4wwm.webp",l="/assets/best-seller.CVGsRqrY.webp",n="/assets/preview-of-bestseller-lists-template.CMC6HjUt.webp",b=JSON.parse('{"title":"BestSeller Lists","description":"","frontmatter":{},"headers":[],"relativePath":"guide/available-products-templates/bestseller-lists.md","filePath":"guide/available-products-templates/bestseller-lists.md"}'),p={name:"guide/available-products-templates/bestseller-lists.md"};function d(c,s,g,h,u,m){return o(),t("div",null,[...s[0]||(s[0]=[r('<h1 id="bestseller-lists" tabindex="-1">BestSeller Lists <a class="header-anchor" href="#bestseller-lists" aria-label="Permalink to &quot;BestSeller Lists&quot;">​</a></h1><p>AzonPress offers an advanced feature to <strong>display Amazon products</strong> using the <strong>WordPress Classic Editor</strong>. This article guides you through using the <strong>BestSeller Lists</strong> of <strong>AzonPress</strong> in the <strong>Classic Editor</strong> of <strong>WordPress</strong>.</p><h2 id="bestseller-lists-of-azonpress" tabindex="-1">BestSeller Lists of AzonPress <a class="header-anchor" href="#bestseller-lists-of-azonpress" aria-label="Permalink to &quot;BestSeller Lists of AzonPress&quot;">​</a></h2><p>You can use the BestSeller Lists to exhibit your best-selling products so that customers can easily conceive the ins and outs of a product.</p><p>To learn how to use BestSeller Lists options, follow the steps with the screenshots below –</p><p>First, add the <strong>Classic Editor</strong> block on your desired Page/Post (e.g., I have added the classic editor to a new post).</p><p>Now, to add the <strong>Classic Editor</strong>, click the Gutenberg editor&#39;s <strong>Plus (+) icon</strong>.</p><p><img src="'+a+'" alt="Add Classic editor block in a post"></p><p>Next, click the <strong>Add Media</strong> option from the <strong>classic editor</strong> bar, and a pop-up window appears with a couple of options.</p><p><img src="'+i+'" alt="Add media option from the classic editor"></p><p>Now, press <strong>AzonPress</strong> from the left sidebar and you will get <strong>BestSeller Lists</strong> tabs with various <strong>settings options</strong> for <strong>showcasing</strong> your <strong>Amazon products.</strong></p><p>To learn the use of these settings options in detail, read this <a href="/guide/getting-started/how-to-use-azonpress-with-classic-editor-gutenberg-block.html">Documentation</a>.</p><p><img src="'+l+'" alt="Best Seller tab"></p><p>Here, is the preview of the post where the selected Amazon Products are displayed as BestSeller Lists.</p><p><img src="'+n+'" alt="Preview of BestSeller Lists template"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',17)])])}const _=e(p,[["render",d]]);export{b as __pageData,_ as default};
